from taf.ul.ettf.msg_capture.expectations import ExpectationsManager
from taf.ul.ettf.ta_matchers.matchers import Any, Contains, MatchingExpectations, Perm
from taf.ul.ettf.typed.typed import typed
from taf.ul.ettf.msg_capture.expectation_builders.detailed import MessageDetail


class common(ExpectationsManager):
    def with_n3pucch_an_list_r13_item(self):
        self.append_expectation(MessageDetail('n3PUCCH-AN-List-r13', Any(), Perm))

    @typed(t_reordering=str)
    def with_srb_item(self, t_reordering):
        srb_item = Any({
            'SRB-ToAddMod': MatchingExpectations({
                't-Reordering': [t_reordering]
            })
        })
        self.append_expectation(MessageDetail('srb-ToAddModList', srb_item, Contains))
